from pathlib import Path
p=Path('work/CompleteEdition/mod-menu/ModMenuUI.cpp');s=p.read_text()
s=s.replace('#include <vector>\n#include <cstdio>\n#include <cstring>\n#include <algorithm>\n','')
s=s.replace('wcslen(file)','lstrlenW(file)').replace('wcscat_s(path,','lstrcatW(path,')
s=s.replace('std::vector<unsigned char> data(bytes);','BYTE* data=(BYTE*)VirtualAlloc(0,bytes,MEM_RESERVE|MEM_COMMIT,PAGE_READWRITE);\n if(!data){CloseHandle(f);return {};}')
s=s.replace('data.data()','data')
s=s.replace('return ok?OverlayHost::CreateTextureRGBA(runtime,w,h,data):OverlayHost::Texture{};','auto texture=ok?OverlayHost::CreateTextureRGBA(runtime,w,h,data):OverlayHost::Texture{};VirtualFree(data,0,MEM_RELEASE);return texture;')
s=s.replace('sequence=(std::max)(sequence,state.lastCommandId)+1','sequence=(sequence>state.lastCommandId?sequence:state.lastCommandId)+1')
s=s.replace('strcpy_s(localMessage,"Another action is finishing. Try again in a moment.")','lstrcpynA(localMessage,"Another action is finishing. Try again in a moment.",128)')
s=s.replace('sprintf_s(speedText,"%.0f",slider)','wsprintfA(speedText,"%d",int(slider))').replace('sprintf_s(balance,"%d",i?state.pixar:state.coins)','wsprintfA(balance,"%d",i?state.pixar:state.coins)').replace('strcpy_s(balance,"--")','lstrcpynA(balance,"--",32)')
s=s.replace('(std::max)(0.f,(std::min)(1.f,','Max(0.f,Min(1.f,')
s=s.replace('scale=(std::min)(1.35f,(std::min)((viewport.x-32)/960,(viewport.y-32)/640))','scale=Min(1.35f,Min((viewport.x-32)/960,(viewport.y-32)/640))')
s=s.replace('strcpy_s(clipped,message)','lstrcpynA(clipped,message,128)').replace('strlen(clipped)','lstrlenA(clipped)')
s=s.replace('using namespace CheatMenuAssets;','using namespace CheatMenuAssets;\nstatic float Min(float a,float b){return a<b?a:b;}\nstatic float Max(float a,float b){return a>b?a:b;}')
s=s.replace(' if(Ready()&&ImGui::IsItemDeactivatedAfterEdit())Send(TS3CheatFlightSpeed,0,slider);\n','')
p.write_text(s)
